#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long maxScore(vector<int>& prices) {
        unordered_map<long long,long long> sums;
        long long ans=LLONG_MIN;
        for(int i=0;i<(int)prices.size();++i) {
            long long key=(long long)prices[i]-i;
            sums[key]+=prices[i];ans=max(ans,sums[key]);
        }
        return ans;
    }
};
